const input = $input.first().json;

if (input.callback_query) {
  const data = input.callback_query.data;
  const chatId = input.callback_query.message.chat.id;

  function parseAction(prefix) {
    if (!data.startsWith(prefix + ':')) return null;
    return data.substring(prefix.length + 1);
  }

  const regenCvId = parseAction('regen_prompt');
  if (data === 'regen_prompt' || regenCvId) {
    const cvId = regenCvId || null;
    return [{ json: { action: 'ask_prompt', chatId, cvId } }];
  }

  const scaleCvId = parseAction('regen_scale');
  if (data === 'regen_scale' || scaleCvId) {
    const cvId = scaleCvId || null;
    return [{ json: { action: 'show_scale', chatId, cvId } }];
  }

  if (data.startsWith('scale_')) {
    const parts = data.replace('scale_', '').split(':');
    const scale = parseFloat(parts[0]);
    const cvId = parts[1] || null;
    return [{ json: { action: 'apply_scale', chatId, scale, cvId } }];
  }

  const themeCvId = parseAction('change_theme');
  if (data === 'change_theme' || themeCvId) {
    const cvId = themeCvId || null;
    return [{ json: { action: 'show_themes', chatId, cvId } }];
  }

  if (data.startsWith('theme_')) {
    const parts = data.replace('theme_', '').split(':');
    const theme = parts[0];
    const cvId = parts[1] || null;
    return [{ json: { action: 'apply_theme', chatId, theme, cvId } }];
  }

  // Default theme (no cvId needed)
  if (data === 'set_default_theme') {
    return [{ json: { action: 'show_default_themes', chatId } }];
  }

  if (data.startsWith('default_theme_')) {
    const theme = data.replace('default_theme_', '');
    return [{ json: { action: 'confirm_default', chatId, theme } }];
  }
}

// Text message → regen prompt
// NOTE: if no callback,
// For now, if there's a text message and no callback, treat it as a regen prompt.
if (input.message && input.message.text && !input.message.text.startsWith('/')) {
  const chatId = input.message.chat.id;
  const prompt = input.message.text;
  return [{ json: { action: 'regenerate', chatId, userPrompt: prompt, cvId: null } }];
}

return [];

const cvId = $input.first().json.cvId || '';
const scales = [0.7, 0.75, 0.8, 0.85, 0.9, 1.0];
const keyboard = [];
for (let i = 0; i < scales.length; i += 3) {
  keyboard.push(
    scales.slice(i, i + 3).map(s => ({
      text: `${s}×`,
      callback_data: `scale_${s}:${cvId}`
    }))
  );
}

return [{
  json: {
    ...$input.first().json,
    scaleMarkup: JSON.stringify({ inline_keyboard: keyboard })
  }
}];

const cvId = $input.first().json.label;
const chatId = $input.first().json.chatId;
const userPrompt = $input.first().json.userPrompt;

const resumeJson = $input.first().json.resumeJson;
const company = $input.first().json.company || 'Resume';

if (!resumeJson) {
  throw new Error('No saved CV found. Generate one from a job listing first.');
}

const resume = JSON.parse(resumeJson);

const locked = {
  full_name: resume.full_name,
  contact: resume.contact,
  education: resume.education,
  languages: resume.languages,
  achievements: resume.achievements
};

const modifiable = {
  headline: resume.headline,
  summary: resume.summary,
  experience: resume.experience,
  skills: resume.skills
};

return [{ json: { locked, modifiable, userPrompt, chatId, companyName: company, cvId } }];

const cvId = $input.first().json.label;
const chatId = $input.first().json.chatId;
const action = $('Parse Regen Action').first().json;
const theme = action.theme;
const resumeJson = $input.first().json.resumeJson;

const htmlContent = $input.first().json.htmlContent;
const companyName = $input.first().json.company || 'Resume';

if (!htmlContent) {
  return [{ json: { action: 'error', chatId, errorMessage: '❌ Резюме не знайдено.' } }];
}

return [{ json: { htmlContent, chatId, companyName, theme, cvId, resumeJson } }];

const cvId = $input.first().json.label;
const chatId = $input.first().json.chatId;
const scale = $input.first().json.scale;

// htmlContent should come from a Data Table 'Get Row' node upstream
const htmlContent = $input.first().json.htmlContent;
const companyName = $input.first().json.company || 'Resume';

if (!htmlContent) {
  return [{ json: { action: 'error', chatId, errorMessage: '❌ Не вдалося завантажити резюме.' } }];
}

return [{ json: { htmlContent, chatId, companyName, scale, cvId } }];

const configTheme = $('Configuration').first().json.cv_theme;
const inputTheme = $input.first().json.theme;

// Priority: explicit input > config default
const theme = inputTheme || configTheme || 'classic';

return $input.all().map(item => ({
  json: { ...item.json, resolvedTheme: theme }
}));

const configName = $('Configuration').first().json.candidate_raw_cv.full_name;
const cvId = $input.first().json.cvId;

let resume;
try {
  const locked = $('Load Last Resume').first().json.locked;
  const modified = $('LLM: Regen Resume').first().json.output;
  resume = { ...modified, ...locked };
} catch (e) {
  // Theme change path — resume should come from input JSON (Data Table)
  const resumeJson = $input.first().json.resumeJson;
  resume = resumeJson ? JSON.parse(resumeJson) : {};
}

if (resume.full_name !== configName) {
  resume = $('Configuration').first().json.candidate_raw_cv;
}

return $input.all().map(item => ({
  json: { ...item.json, resume, flow: 'regen', resumeJson: JSON.stringify(resume) }
}));

const resume = $input.first().json.resume;

const calendarIco = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>';
const globeIco = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 010 18M12 3a14 14 0 000 18"/></svg>';
const pinIco = '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2a7 7 0 00-7 7c0 5.2 7 13 7 13s7-7.8 7-13a7 7 0 00-7-7zm0 9.5a2.5 2.5 0 110-5 2.5 2.5 0 010 5z"/></svg>';

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function metaItem(ico, text) {
  return `<span class="item"><span class="ico" aria-hidden="true">${ico}</span>${esc(text)}</span>`;
}

function buildExperience(entries) {
  return entries.map(exp => {
    const locationMeta = exp.location ? metaItem(globeIco, exp.location) : '';
    const bullets = exp.bullets.map(b => `          <li>${esc(b)}</li>`).join('\n');
    return `
      <div class="entry">
        <p class="role">${esc(exp.title)}</p>
        <div class="org">${esc(exp.org)}</div>
        <div class="meta">
          ${metaItem(calendarIco, exp.date)}
          ${locationMeta}
        </div>
        <ul class="bullets">
${bullets}
        </ul>
      </div>`;
  }).join('\n');
}

function buildEducation(entries) {
  return entries.map(edu => `
      <div class="entry">
        <p class="role">${esc(edu.degree)}</p>
        <div class="school">${esc(edu.school)}</div>
        <div class="meta">
          ${metaItem(calendarIco, edu.date)}
          ${metaItem(pinIco, edu.location)}
        </div>
      </div>`).join('\n');
}

function buildLanguages(langs) {
  return langs.map(l => {
    const dots = Array.from({ length: 5 }, (_, i) =>
      `<span${i >= l.dots ? ' class="off"' : ''}></span>`
    ).join('');
    return `
        <div class="lang">
          <div class="lname">${esc(l.name)}</div>
          <div class="llevel">${esc(l.level)}</div>
          <div class="dots">${dots}</div>
        </div>`;
  }).join('\n');
}

function buildAchievements(achs) {
  return achs.map(a => `
      <div class="ach">
        <div>
          <p class="title">${esc(a.title)}</p>
          <div class="body">${esc(a.body)}</div>
        </div>
      </div>`).join('\n');
}

function buildChips(skills) {
  return skills.map(s => `<span class="chip">${esc(s)}</span>`).join('\n          ');
}

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<title>${esc(resume.full_name)} — Resume</title>
<meta name="viewport" content="width=device-width,initial-scale=1" />
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@400;600;700;900&display=swap" rel="stylesheet">
<style>
