<meta name="viewport" content="width=device-width,initial-scale=1" />
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600;700&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root {
    --ink:        #1f1f1f;
    --ink-soft:   #444746;
    --ink-mute:   #80868b;
    --line:       #e8eaed;
    --line-soft:  #f1f3f4;
    --surface:    #ffffff;
    --surface-2:  #f8f9fb;
    --chip:       #f0f4f9;
    --chip-ink:   #1f1f1f;

    /* Gemini-ish gradient */
    --g1: #4285f4;
    --g2: #9b72f2;
    --g3: #d96570;
    --g4: #f2a856;
    --accent: #1a73e8;
    --grad: linear-gradient(135deg, var(--g1) 0%, var(--g2) 38%, var(--g3) 72%, var(--g4) 100%);
  }

  * { box-sizing: border-box; }

  html, body { margin: 0; padding: 0; }
  body {
    background: #ffffff;
    color: var(--ink);
    font-family: "Geist", "Google Sans", "Helvetica Neue", Arial, sans-serif;
    font-size: 13px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    display: flex;
    justify-content: center;
  }

  /* ============ Sheet ============ */
  .sheet {
    width: 100%;
    max-width: 820px;
    background: var(--surface);
    border-radius: 0;
    padding: 24px 32px;
    position: relative;
    border: none;
    box-shadow: none;
  }

  /* ============ Header ============ */
  .header { margin-bottom: 16px; }
  .head-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 10px;
  }
  .avatar {
    width: 52px; height: 52px;
    border-radius: 50%;
    background: var(--grad);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-weight: 600;
    font-size: 20px;
    letter-spacing: -.01em;
    flex-shrink: 0;
  }
  .head-text { min-width: 0; flex: 1; }

  .name {
    font-weight: 500;
    font-size: 28px;
    letter-spacing: -.025em;
    line-height: 1.1;
    margin: 0;
    color: var(--ink);
  }
  .name .gradient {
    background: var(--grad);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    font-weight: 600;
  }
  .tagline {
    font-weight: 400;
    font-size: 13.5px;
    color: var(--ink-soft);
    line-height: 1.4;
    margin: 2px 0 0;
  }
  .availability {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--surface-2);
    border: 1px solid var(--line);
    color: var(--ink-soft);
    font-size: 11px;
    font-weight: 500;
    padding: 4px 10px 4px 8px;
    border-radius: 100px;
    margin-bottom: 12px;
  }
  .availability .dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: #1e8e3e;
    box-shadow: 0 0 0 3px rgba(30,142,62,.18);
  }

  .contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 5px 8px;
  }
  .contacts a, .contacts span.item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11.5px;
    color: var(--ink-soft);
    text-decoration: none;
    background: var(--surface-2);
    border: 1px solid var(--line);
    padding: 4px 10px;
    border-radius: 100px;
    white-space: nowrap;
  }
  .contacts .ico {
    color: var(--ink-mute);
    width: 12px; height: 12px;
    display: inline-flex; flex-shrink: 0;
  }
  .contacts .ico svg { width: 100%; height: 100%; }

  /* ============ Two-column (float) ============ */
  .grid { margin-top: 4px; }
  .grid::after { content: ""; display: block; clear: both; }
  .col-left  { float: left;  width: 56%; padding-right: 20px; }
  .col-right { float: right; width: 44%; padding-left: 20px; border-left: 1px solid var(--line); }

  /* ============ Section headings ============ */
  h2.section {
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--ink-mute);
    margin: 16px 0 8px;
    padding: 0;
    border: none;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  h2.section:first-child { margin-top: 0; }
  h2.section::before {
    content: "";
    width: 4px; height: 4px;
    border-radius: 50%;
    background: var(--grad);
    flex-shrink: 0;
  }

  /* ============ Entries ============ */
  .entry {
    margin-bottom: 12px;
    padding: 0;
  }
  .entry:last-child { margin-bottom: 4px; }

  .role-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 0px;
  }
  .role {
    font-weight: 600;
    font-size: 13.5px;
    letter-spacing: -.01em;
    color: var(--ink);
    margin: 0;
    line-height: 1.3;
  }
  .when {
    font-family: "Geist Mono", monospace;
    font-size: 10.5px;
    color: var(--ink-mute);
    white-space: nowrap;
    font-weight: 400;
  }
  .org {
    font-weight: 500;
    font-size: 12.5px;
    color: var(--accent);
    margin: 0 0 4px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .org .where {
    color: var(--ink-mute);
    font-weight: 400;
  }
  .org .where::before {
    content: "·";
    margin-right: 6px;
    color: var(--ink-mute);
  }

  ul.bullets {
    margin: 4px 0 0;
    padding: 0;
    list-style: none;
  }
  ul.bullets li {
    position: relative;
    padding-left: 14px;
    margin-bottom: 3px;
    font-size: 12px;
    color: var(--ink-soft);
    line-height: 1.4;
  }
  ul.bullets li::before {
    content: "";
    position: absolute;
    left: 2px;
    top: 6px;
    width: 4px; height: 4px;
    border-radius: 50%;
    background: var(--line);
  }

  .school {
    font-weight: 500;
    color: var(--accent);
    font-size: 12.5px;
  }

  /* ============ Languages ============ */
  .langs { margin-top: 2px; }
  .langs::after { content: ""; display: block; clear: both; }
  .lang {
    float: left;
    width: 50%;
    padding-right: 12px;
    margin-bottom: 6px;
  }
  .lang .lname {
    font-weight: 500;
    font-size: 12.5px;
    color: var(--ink);
  }
  .lang .llevel {
    font-size: 10.5px;
    color: var(--ink-mute);
    margin: 0 0 4px;
  }
  .bars {
    display: flex;
    gap: 3px;
    height: 4px;
  }
  .bars span {
    flex: 1;
    background: var(--line);
    border-radius: 100px;
  }
  .bars span.on { background: var(--grad); }

  /* ============ Summary card ============ */
  .summary-card {
    background: linear-gradient(135deg, rgba(66,133,244,.04), rgba(155,114,242,.04) 50%, rgba(217,101,112,.04));
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 12px 14px;
    position: relative;
    overflow: hidden;
  }
  .summary-card::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: var(--grad);
    opacity: .6;
  }
  .summary {
    font-size: 12px;
    line-height: 1.45;
    color: var(--ink-soft);
    margin: 0;
    text-wrap: pretty;
  }

  /* ============ Achievements ============ */
  .ach {
    margin-bottom: 8px;
    padding: 10px 12px;
    background: var(--surface-2);
    border: 1px solid var(--line);
    border-radius: 12px;
    display: flex;
    gap: 10px;
    align-items: flex-start;
  }
  .ach .mark {
    width: 22px; height: 22px;
    border-radius: 6px;
    background: var(--grad);
    color: #fff;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 10px;
    font-family: "Geist Mono", monospace;
  }
  .ach .body { flex: 1; min-width: 0; }
  .ach .title {
    font-weight: 600;
    font-size: 12.5px;
    color: var(--ink);
    margin: 0 0 2px;
    line-height: 1.3;
  }
  .ach .desc {
    font-size: 11.5px;
    color: var(--ink-soft);
    line-height: 1.35;
  }

  /* ============ Skills ============ */
  .skill-group { margin-bottom: 10px; }
  .skill-group h3 {
    font-size: 10.5px;
    font-weight: 600;
    color: var(--ink);
    margin: 2px 0 6px;
  }
  .chips { display: flex; flex-wrap: wrap; gap: 4px; }
  .chip {
    background: var(--chip);
    color: var(--chip-ink);
    border: 1px solid transparent;
    font-size: 10.5px;
    font-weight: 500;
    padding: 3px 8px;
    border-radius: 100px;
    line-height: 1.25;
    white-space: nowrap;
  }
  .chip.primary {
    background: #fff;
    border-color: transparent;
    background-image:
      linear-gradient(#fff, #fff),
      var(--grad);
    background-origin: border-box;
    background-clip: padding-box, border-box;
    color: var(--ink);
  }

  /* ============ Print ============ */
  @media print {
    body { padding: 0; }
    .sheet { padding: 16px 24px; }
  }

  /* ============ Narrow viewport ============ */
  @media (max-width: 720px) {
    .col-left, .col-right { float: none; width: 100%; padding: 0; border: none; }
    .col-right { margin-top: 12px; }
    .lang { float: none; width: 100%; padding: 0; }
    .sheet { padding: 24px 16px; border-radius: 0; }
    .name { font-size: 24px; }
    .role-row { flex-wrap: wrap; }
  }
</style>
</head>
<body>

<main class="sheet" data-screen-label="Resume">

  <!-- ======= Header ======= -->
  <header class="header">
    <div class="head-row">
      <div class="avatar" aria-hidden="true">${getInitials(resume.full_name)}</div>
      <div class="head-text">
        <h1 class="name">${formatName(resume.full_name)}</h1>
        <p class="tagline">${esc(resume.headline)}</p>
      </div>
    </div>

    <span class="availability"><span class="dot"></span> Available · ${esc((resume.headline.match(/On-site|Remote|Hybrid/gi) || ['On-site / Remote']).join(' / '))}</span>

    <div class="contacts">
      <span class="item">
        <span class="ico" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="currentColor"><path d="M6.6 10.8c1.4 2.8 3.8 5.1 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.2.4 2.4.6 3.7.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1C10.6 21 3 13.4 3 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.7.1.4 0 .7-.2 1l-2.3 2.1z"/></svg>
        </span>
        ${esc(resume.contact.phone)}
      </span>
      <a href="mailto:${esc(resume.contact.email)}">
        <span class="ico" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/></svg>
        </span>
        ${esc(resume.contact.email)}
      </a>
      <a href="${esc(resume.contact.linkedin)}" target="_blank" rel="noopener">
        <span class="ico" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="currentColor"><path d="M4.98 3.5a2.5 2.5 0 11.02 5 2.5 2.5 0 01-.02-5zM3 9h4v12H3V9zm7 0h3.8v1.7h.05c.53-.95 1.83-1.95 3.77-1.95 4.03 0 4.78 2.65 4.78 6.1V21h-4v-5.4c0-1.29-.02-2.95-1.8-2.95-1.8 0-2.08 1.4-2.08 2.85V21h-4V9z"/></svg>
        </span>
        ${esc(resume.contact.linkedin).replace('https://www.', '')}
      </a>
      <span class="item">
        <span class="ico" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2a7 7 0 00-7 7c0 5.2 7 13 7 13s7-7.8 7-13a7 7 0 00-7-7zm0 9.5a2.5 2.5 0 110-5 2.5 2.5 0 010 5z"/></svg>
        </span>
        ${esc(resume.contact.location)}
      </span>
    </div>
  </header>

  <!-- ======= Two-column grid ======= -->
  <div class="grid">

    <!-- ============ LEFT COLUMN ============ -->
    <section class="col-left">

      <h2 class="section">Experience</h2>
      ${buildExperience(resume.experience)}

      <h2 class="section">Education</h2>
      ${buildEducation(resume.education)}

      <h2 class="section">Languages</h2>
      <div class="langs">
        ${buildLanguages(resume.languages)}
      </div>

    </section>

    <!-- ============ RIGHT COLUMN ============ -->
    <section class="col-right">

      <h2 class="section">Summary</h2>
      <div class="summary-card">
        <p class="summary">
          ${esc(resume.summary)}
        </p>
      </div>

      <h2 class="section">Key Achievements</h2>
      ${buildAchievements(resume.achievements)}

      <h2 class="section">Skills</h2>

      <div class="skill-group">
        <h3>Frontend</h3>
        <div class="chips">
          ${buildChips(resume.skills.frontend)}
        </div>
      </div>

      <div class="skill-group">
        <h3>Backend</h3>
        <div class="chips">
          ${buildChips(resume.skills.backend)}
        </div>
      </div>

    </section>
  </div>

</main>

</body>
</html>`;

return [{ json: { ...$input.first().json, htmlContent: html } }];

const resume = $input.first().json.resume;

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildExperience(entries) {
  return entries.map(exp => {
    const locationMeta = exp.location ? `<div class="where">${esc(exp.location)}</div>` : '';
    const bullets = exp.bullets.map(b => `          <li>${esc(b)}</li>`).join('\n');
    return `
          <div class="entry">
            <div class="role-row">
              <p class="role">${esc(exp.title)}</p>
              <span class="when">${esc(exp.date)}</span>
            </div>
            <div class="org"><span class="accent">${esc(exp.org)}</span></div>
            ${locationMeta}
            <ul class="bullets">
${bullets}
            </ul>
          </div>`;
  }).join('\n');
}

function buildEducation(entries) {
  return entries.map(edu => {
    const locationMeta = edu.location ? `<div class="where">${esc(edu.location)}</div>` : '';
    return `
          <div class="entry">
            <div class="role-row">
              <p class="role">${esc(edu.degree)}</p>
              <span class="when">${esc(edu.date)}</span>
            </div>
            <div class="org"><span class="accent">${esc(edu.school)}</span></div>
            ${locationMeta}
          </div>`;
  }).join('\n');
}

function buildLanguages(langs) {
  return langs.map(l => {
    const bars = Array.from({ length: 5 }, (_, i) =>
      `<span${i < l.dots ? ' class="on"' : ''}></span>`
    ).join('');
    return `
            <div class="lang">
              <div class="lname">${esc(l.name)}</div>
              <div class="llevel">${esc(l.level)}</div>
              <div class="bars">${bars}</div>
            </div>`;
  }).join('\n');
}

function buildAchievements(achs) {
  return achs.map(a => {
    return `
          <div class="ach">
            <span class="check" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="5 12 10 17 19 7"/></svg>
            </span>
            <div class="body">
              <p class="title">${esc(a.title)}</p>
              <div class="desc">${esc(a.body)}</div>
            </div>
          </div>`;
  }).join('\n');
}

function buildChips(skills) {
  return skills.map((s, index) => {
    const primaryClass = index < 2 ? ' primary' : '';
    return `<span class="chip${primaryClass}">${esc(s)}</span>`;
  }).join('\n              ');
}

