<style>
  :root {
    --ink:        #0d0d0d;
    --ink-soft:   #353740;
    --ink-mute:   #6e6e80;
    --line:       #e5e5e5;
    --line-soft:  #ececec;
    --surface:    #ffffff;
    --bg:         #ffffff;
    --chip:       #ececec;
    --chip-ink:   #353740;
    --accent:     #10a37f;
    --accent-soft:#d1f0e3;
  }

  * { box-sizing: border-box; }

  html, body { margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--ink);
    font-family: "Public Sans", "Söhne", "Helvetica Neue", Arial, sans-serif;
    font-size: 12.5px;
    line-height: 1.4;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    padding: 0;
    display: flex;
    justify-content: center;
  }

  /* ============ Sheet (a ChatGPT-like assistant card) ============ */
  .sheet {
    width: 100%;
    max-width: 860px;
    background: var(--surface);
    border-radius: 0;
    border: none;
    padding: 0;
    overflow: hidden;
    box-shadow: none;
  }

  /* ============ Top bar (mimics chat header) ============ */
  .topbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 16px;
    border-bottom: 1px solid var(--line);
    background: #fcfcfc;
  }
  .topbar .knot {
    width: 20px; height: 20px;
    color: var(--ink);
    flex-shrink: 0;
  }
  .topbar .title {
    font-weight: 500;
    font-size: 13px;
    color: var(--ink);
    flex: 1;
  }
  .topbar .pill {
    font-size: 11px;
    color: var(--ink-mute);
    background: var(--surface);
    border: 1px solid var(--line);
    padding: 2px 8px;
    border-radius: 100px;
    display: inline-flex;
    align-items: center;
    gap: 5px;
  }
  .topbar .pill .dot {
    width: 5px; height: 5px;
    border-radius: 50%;
