  }

  /* ============ Assistant reply container ============ */
  .reply {
    padding: 4px 16px 12px;
    display: flex;
    gap: 10px;
  }
  .reply .avatar {
    width: 24px; height: 24px;
    border-radius: 50%;
    background: var(--ink);
    color: #fff;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: 4px;
  }
  .reply .avatar svg { width: 14px; height: 14px; }
  .reply .body { flex: 1; min-width: 0; }

  /* ============ Header (inside reply) ============ */
  .header { margin-bottom: 10px; }
  .name {
    font-weight: 600;
    font-size: 22px;
    letter-spacing: -.02em;
    line-height: 1.1;
    margin: 0 0 2px;
    color: var(--ink);
  }
  .tagline {
    font-size: 12px;
    color: var(--ink-soft);
    margin: 0 0 6px;
    line-height: 1.35;
  }
  .contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 6px;
  }
  .contacts a, .contacts span.item {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 11px;
    color: var(--ink-soft);
    text-decoration: none;
    border: 1px solid var(--line);
    padding: 2px 8px;
    border-radius: 6px;
    white-space: nowrap;
    background: var(--surface);
  }
  .contacts .ico {
    color: var(--ink-mute);
    width: 11px; height: 11px;
    display: inline-flex;
  }
  .contacts .ico svg { width: 100%; height: 100%; }

  /* ============ Two-column (float) ============ */
  .grid { margin-top: 4px; }
  .grid::after { content: ""; display: block; clear: both; }
  .col-left  { float: left;  width: 58%; padding-right: 16px; }
  .col-right { float: right; width: 42%; padding-left: 16px; border-left: 1px solid var(--line); }

  /* ============ Section headings ============ */
  h2.section {
    font-size: 13px;
