    font-family: "JetBrains Mono", monospace;
    font-weight: 400;
    font-size: 11.5px;
  }

  /* ============ Entries ============ */
  .entry {
    margin-bottom: 8px;
    padding: 0;
  }
  .entry:last-child { margin-bottom: 2px; }

  .role-row {
    display: flex;
