  }
  .org .accent { color: var(--accent); font-weight: 500; }
  .org .where::before {
    content: " · ";
    color: var(--line);
  }

  ul.bullets {
    margin: 2px 0 0;
    padding: 0;
    list-style: none;
  }
  ul.bullets li {
    position: relative;
    padding-left: 12px;
    margin-bottom: 2px;
    font-size: 11.5px;
    color: var(--ink-soft);
    line-height: 1.35;
  }
  ul.bullets li::before {
    content: "";
    position: absolute;
    left: 2px; top: 6px;
    width: 3px; height: 3px;
    border-radius: 50%;
    background: var(--ink-mute);
  }

  /* ============ Languages ============ */
  .langs { margin-top: 2px; }
  .langs::after { content: ""; display: block; clear: both; }
  .lang {
    float: left;
    width: 50%;
    padding-right: 10px;
    margin-bottom: 6px;
  }
  .lang .lname {
    font-weight: 500;
    font-size: 12.5px;
    color: var(--ink);
  }
  .lang .llevel {
    font-size: 10.5px;
    color: var(--ink-mute);
    margin: 0 0 4px;
  }
  .bars {
    display: flex;
    gap: 3px;
    height: 3px;
  }
  .bars span {
    flex: 1;
    background: var(--line);
    border-radius: 100px;
  }
  .bars span.on { background: var(--accent); }

  /* ============ Summary callout ============ */
  .callout {
    background: #f7f7f8;
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 8px 10px;
    margin: 2px 0;
  }
  .summary {
    font-size: 11.5px;
    line-height: 1.4;
    color: var(--ink-soft);
    margin: 0;
    text-wrap: pretty;
  }

  /* ============ Achievements ============ */
  .ach {
