    --line-soft:  #f0f0f2;
    --ink:        #0d0d0d;
    --ink-soft:   #353740;
    --ink-mute:   #6e6e80;
    --ink-dim:    #a3a3ac;
    --accent:     #0d0d0d;
    --hot:        #1d9bf0;
    --hot-soft:   rgba(29,155,240,.18);
  }

  * { box-sizing: border-box; }

  html, body { margin: 0; padding: 0; background: #ffffff; }
  body {
    color: var(--ink);
    font-family: "Manrope", "Inter Tight", "Helvetica Neue", Arial, sans-serif;
    font-size: 13.5px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    padding: 0;
    display: flex;
    justify-content: center;
    min-height: 100vh;
  }

  /* ============ Sheet ============ */
  .sheet {
    width: 100%;
    max-width: 880px;
    background: var(--surface);
    border-radius: 0;
    border: 1px solid var(--line);
    padding: 0;
    overflow: hidden;
    position: relative;
  }

  /* faint hairline grid overlay for tech feel */
  .sheet::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(to right, rgba(0,0,0,.018) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(0,0,0,.018) 1px, transparent 1px);
    background-size: 32px 32px;
    pointer-events: none;
    z-index: 0;
  }
  .sheet > * { position: relative; z-index: 1; }

  /* ============ Top bar ============ */
  .topbar {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 11px 18px;
    border-bottom: 1px solid var(--line);
    background: var(--surface);
  }
  .mark {
    width: 22px; height: 22px;
    background: var(--ink);
    color: #fff;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 13px;
    line-height: 1;
    flex-shrink: 0;
  }
  .topbar .title {
    font-weight: 600;
    font-size: 13px;
    color: var(--ink);
    flex: 1;
    letter-spacing: -.005em;
  }
  .topbar .title .sub {
    color: var(--ink-mute);
    font-weight: 400;
    margin-left: 6px;
  }
  .topbar .meta {
    font-family: "JetBrains Mono", monospace;
    font-size: 10.5px;
    color: var(--ink-mute);
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .topbar .meta .dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--hot);
    box-shadow: 0 0 0 3px var(--hot-soft);
    animation: pulse 2.4s ease-in-out infinite;
  }
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: .55; }
  }

  /* ============ Header band ============ */
  .header {
    padding: 16px 20px 14px;
    border-bottom: 1px solid var(--line);
  }
  .eyebrow {
    font-family: "JetBrains Mono", monospace;
    font-size: 10px;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: var(--ink-dim);
    margin-bottom: 10px;
    display: flex;
    justify-content: space-between;
