  .eyebrow .right { color: var(--ink-mute); }
  .name {
    font-weight: 700;
    font-size: 38px;
    letter-spacing: -.035em;
    line-height: 1;
    margin: 0 0 6px;
    color: var(--ink);
  }
  .tagline {
    font-weight: 400;
    font-size: 13.5px;
    color: var(--ink-mute);
    margin: 8px 0 14px;
    line-height: 1.45;
    max-width: 78%;
  }
  .contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 6px;
  }
  .contacts a, .contacts span.item {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    font-size: 11.5px;
    color: var(--ink-soft);
    text-decoration: none;
    border: 1px solid var(--line);
    padding: 4px 10px;
    border-radius: 6px;
    white-space: nowrap;
    background: var(--surface-2);
