    color: var(--ink-mute);
    width: 12px; height: 12px;
    display: inline-flex;
  }
  .contacts .ico svg { width: 100%; height: 100%; }

  /* ============ Two-column (float) ============ */
  .main { padding: 16px 20px 20px; }
  .grid::after { content: ""; display: block; clear: both; }
  .col-left  { float: left;  width: 58%; padding-right: 22px; }
  .col-right { float: right; width: 42%; padding-left: 20px; border-left: 1px solid var(--line); }

  /* ============ Section headings ============ */
  h2.section {
    font-family: "JetBrains Mono", monospace;
    font-size: 10.5px;
    font-weight: 500;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: var(--ink-mute);
    margin: 18px 0 10px;
    padding: 0 0 6px;
    border-bottom: 1px solid var(--line);
    display: flex;
    align-items: center;
    gap: 8px;
