  h2.section:first-child { margin-top: 0; }
  h2.section::before {
    content: "▍";
    color: var(--ink);
    font-size: 11px;
    line-height: 1;
  }

  /* ============ Entries ============ */
  .entry {
    margin-bottom: 12px;
  }
  .entry:last-child { margin-bottom: 2px; }

  .role-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 1px;
  }
  .role {
    font-weight: 600;
    font-size: 14px;
    color: var(--ink);
    margin: 0;
    line-height: 1.3;
    letter-spacing: -.01em;
  }
  .when {
    font-family: "JetBrains Mono", monospace;
    font-size: 10.5px;
    color: var(--ink-dim);
    white-space: nowrap;
    font-weight: 400;
    letter-spacing: .02em;
  }
  .org {
    font-size: 12.5px;
    color: var(--ink-mute);
    margin: 0 0 4px;
    line-height: 1.4;
  }
  .org .accent { color: var(--ink-soft); font-weight: 500; }
  .org .where::before {
    content: " · ";
    color: var(--ink-dim);
  }

  ul.bullets {
    margin: 4px 0 0;
    padding: 0;
    list-style: none;
  }
  ul.bullets li {
    position: relative;
    padding-left: 14px;
    margin-bottom: 3px;
    font-size: 12.5px;
    color: var(--ink-soft);
    line-height: 1.5;
  }
  ul.bullets li::before {
    content: "—";
    position: absolute;
    left: 0; top: 0;
    color: var(--ink-dim);
    font-weight: 500;
  }

  /* ============ Languages ============ */
  .langs::after { content: ""; display: block; clear: both; }
