  .bars span.on { background: var(--ink); }

  /* ============ Summary ============ */
  .summary-wrap {
    background: var(--surface-2);
    border: 1px solid var(--line);
    border-radius: 4px;
    padding: 12px 14px;
    margin-top: 2px;
