  }
  .summary-wrap::before {
    content: "//";
    position: absolute;
    top: 10px; left: 14px;
    font-family: "JetBrains Mono", monospace;
    font-size: 10px;
    color: var(--ink-dim);
    letter-spacing: .1em;
  }
  .summary {
    font-size: 12.8px;
    line-height: 1.55;
    color: var(--ink-soft);
    margin: 14px 0 0;
    text-wrap: pretty;
  }

  /* ============ Achievements ============ */
  .ach {
    margin-bottom: 10px;
    padding: 10px 12px;
    background: var(--surface-2);
    border: 1px solid var(--line);
    border-radius: 4px;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    transition: border-color .15s;
  }
  .ach:hover { border-color: #d4d4d8; }
  .ach .num {
    font-family: "JetBrains Mono", monospace;
    font-size: 11px;
    color: var(--ink-dim);
    flex-shrink: 0;
    padding-top: 1px;
    letter-spacing: .04em;
  }
  .ach .body { flex: 1; min-width: 0; }
  .ach .title {
    font-weight: 600;
    font-size: 13px;
    color: var(--ink);
    margin: 0 0 2px;
    line-height: 1.3;
    letter-spacing: -.005em;
  }
  .ach .desc {
    font-size: 12.3px;
    color: var(--ink-mute);
    line-height: 1.45;
  }

  /* ============ Skills ============ */
  .skill-group { margin-bottom: 10px; }
  .skill-group h3 {
    font-family: "JetBrains Mono", monospace;
    font-size: 10px;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--ink-mute);
    margin: 4px 0 6px;
    font-weight: 500;
  }
  .skill-group h3::before {
    content: "$ ";
    color: var(--ink-dim);
  }
  .chips { display: flex; flex-wrap: wrap; gap: 4px; }
  .chip {
    background: var(--surface-2);
    color: var(--ink-soft);
    border: 1px solid var(--line);
    font-family: "Manrope", sans-serif;
    font-size: 11.5px;
    font-weight: 500;
    padding: 3px 9px;
    border-radius: 5px;
    line-height: 1.25;
    white-space: nowrap;
    letter-spacing: -.005em;
    transition: background .15s, border-color .15s, color .15s;
  }
  .chip:hover { background: #f0f0f2; border-color: #d4d4d8; color: var(--ink); }
  .chip.primary {
    background: var(--ink);
    color: #fff;
    border-color: var(--ink);
  }
  .chip.primary:hover { background: #353740; }

  /* ============ Footer ============ */
  .footbar {
    padding: 10px 18px;
    border-top: 1px solid var(--line);
