    font-size: 10px;
    color: var(--ink-dim);
    letter-spacing: .06em;
    text-transform: uppercase;
  }
  .footbar .keys {
    display: inline-flex;
    gap: 6px;
    align-items: center;
  }
  .footbar kbd {
    font-family: "JetBrains Mono", monospace;
    font-size: 9.5px;
    background: var(--surface-2);
    border: 1px solid var(--line);
    padding: 1px 5px;
    border-radius: 3px;
    color: var(--ink-soft);
    text-transform: none;
  }

  /* ============ Print ============ */
  @media print {
    :root { --bg:#fff; --surface:#fff; --surface-2:#fafafa; --ink:#000; --ink-soft:#333; --ink-mute:#666; --ink-dim:#888; --line:#ddd; }
