    gap: 8px;
  }
  .search-bar .filters {
    display: flex;
    gap: 6px;
  }
  .filter-pill {
    font-size: 11.5px;
    background: var(--surface);
    border: 1px solid var(--line);
    color: var(--ink-soft);
    padding: 3px 9px 3px 7px;
    border-radius: 8px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .filter-pill svg { width: 11px; height: 11px; color: var(--ink-mute); }
  .filter-pill.focus { color: var(--teal); border-color: var(--teal); background: var(--teal-tint); }
  .filter-pill.focus svg { color: var(--teal); }
  .search-bar .run {
    width: 28px; height: 28px;
    border-radius: 50%;
    background: var(--ink);
    color: #fff;
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }
  .search-bar .run svg { width: 13px; height: 13px; }

  /* ============ Header band ============ */
  .header {
    padding: 14px 20px 14px;
    border-bottom: 1px solid var(--line-soft);
  }
  .source-row {
    font-family: "IBM Plex Mono", monospace;
    font-size: 11px;
    color: var(--ink-mute);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .source-row .badge {
    background: var(--teal-soft);
    color: var(--teal-deep);
    padding: 2px 8px;
    border-radius: 4px;
    font-weight: 500;
    letter-spacing: .03em;
  }
  .name {
    font-weight: 700;
    font-size: 36px;
    letter-spacing: -.03em;
    line-height: 1.02;
    margin: 0 0 4px;
    color: var(--ink);
  }
  .name .accent { color: var(--teal); }
  .tagline {
    font-size: 14px;
    color: var(--ink-soft);
    margin: 8px 0 14px;
    line-height: 1.5;
    max-width: 80%;
  }
  .contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 6px;
  }
  .contacts a, .contacts span.item {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    font-size: 12px;
    color: var(--ink-soft);
    text-decoration: none;
    border: 1px solid var(--line);
    padding: 4px 11px;
    border-radius: 100px;
    white-space: nowrap;
    background: var(--surface);
    transition: background .15s, border-color .15s, color .15s;
  }
  .contacts a:hover { background: var(--teal-tint); border-color: var(--teal); color: var(--teal-deep); }
  .contacts a:hover .ico { color: var(--teal); }
  .contacts .ico {
    color: var(--ink-mute);
    width: 12px; height: 12px;
    display: inline-flex;
  }
  .contacts .ico svg { width: 100%; height: 100%; }

  /* ============ Two-column (float) ============ */
  .main { padding: 16px 20px 20px; }
  .grid::after { content: ""; display: block; clear: both; }
  .col-left  { float: left;  width: 58%; padding-right: 24px; }
  .col-right { float: right; width: 42%; padding-left: 22px; border-left: 1px solid var(--line-soft); }

  /* ============ Section headings ============ */
  h2.section {
    font-size: 14.5px;
    font-weight: 600;
    letter-spacing: -.015em;
    color: var(--ink);
    margin: 20px 0 11px;
    padding: 0 0 6px;
    border-bottom: 1px solid var(--line);
    display: flex;
    align-items: center;
    gap: 8px;
  }
  h2.section:first-child { margin-top: 0; }
  h2.section .star {
    color: var(--teal);
    flex-shrink: 0;
  }
  h2.section .star svg { width: 12px; height: 12px; display: block; }
  h2.section .count {
    margin-left: auto;
    font-family: "IBM Plex Mono", monospace;
    font-weight: 400;
    font-size: 11px;
    color: var(--ink-dim);
  }

  /* ============ Entries ============ */
  .entry { margin-bottom: 8px; }
  .entry:last-child { margin-bottom: 2px; }

  .role-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 0;
  }
  .role {
    font-weight: 600;
    font-size: 14px;
    color: var(--ink);
    margin: 0;
    line-height: 1.3;
    letter-spacing: -.005em;
  }
  .when {
    font-family: "IBM Plex Mono", monospace;
    font-size: 11px;
    color: var(--ink-mute);
    white-space: nowrap;
    font-weight: 400;
  }
