  .ach .body { flex: 1; min-width: 0; }
  .ach .title {
    font-weight: 600;
    font-size: 13px;
    color: var(--ink);
    margin: 0 0 2px;
    line-height: 1.3;
  }
  .ach .desc {
    font-size: 12.3px;
    color: var(--ink-mute);
    line-height: 1.45;
  }

  /* ============ Skills ============ */
  .skill-group { margin-bottom: 10px; }
  .skill-group h3 {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--ink);
    margin: 4px 0 7px;
