  .chips { display: flex; flex-wrap: wrap; gap: 4px; }
  .chip {
    background: var(--surface);
    color: var(--ink-soft);
    border: 1px solid var(--line);
    font-family: "Plus Jakarta Sans", sans-serif;
    font-size: 11.5px;
    font-weight: 500;
    padding: 3px 10px;
    border-radius: 100px;
    line-height: 1.3;
    white-space: nowrap;
