  .chip:hover { background: var(--teal-tint); border-color: var(--teal); color: var(--teal-deep); }
  .chip.primary {
    background: var(--teal);
    color: #fff;
    border-color: var(--teal);
  }
  .chip.primary:hover { background: var(--teal-deep); color: #fff; }

  /* ============ Print ============ */
  @media print {
    body { background: #fff; padding: 0; }
