return [{ json: { ...$input.first().json, htmlContent: html } }];

const resume = $input.first().json.resume;

function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function buildExperience(entries) {
  return entries.map(exp => {
    const locationMeta = exp.location ? `<span class="where">${esc(exp.location)}</span>` : '';
    const bullets = exp.bullets.map(b => `                <li>${esc(b)}</li>`).join('\n');
    return `
            <div class="entry">
              <div class="role-row">
                <p class="role">${esc(exp.title)}</p>
                <span class="when">${esc(exp.date)}</span>
              </div>
              <div class="org"><span class="accent">${esc(exp.org)}</span>${locationMeta ? '<span class="where">' + esc(exp.location) + '</span>' : ''}</div>
              <ul class="bullets">
${bullets}
              </ul>
            </div>`;
  }).join('\n');
}

function buildEducation(entries) {
  return entries.map(edu => {
    return `
            <div class="entry">
              <div class="role-row">
                <p class="role">${esc(edu.degree)}</p>
                <span class="when">${esc(edu.date)}</span>
              </div>
              <div class="org"><span class="accent">${esc(edu.school)}</span></div>
              ${edu.location ? '<div class="org-loc">' + esc(edu.location) + '</div>' : ''}
            </div>`;
  }).join('\n');
}

function buildLanguages(langs) {
  return langs.map(l => {
    const bars = Array.from({ length: 5 }, (_, i) =>
      `<span${i < l.dots ? ' class="on"' : ''}></span>`
    ).join('');
    return `
              <div class="lang">
                <div class="lname">${esc(l.name)}</div>
                <div class="llevel">${esc(l.level)}</div>
                <div class="bars">${bars}</div>
              </div>`;
  }).join('\n');
}

function buildAchievements(achs) {
  return achs.map((a, index) => {
    const num = String(index + 1).padStart(2, '0');
    return `
            <div class="ach">
              <p class="title"><span class="num">${num}</span>${esc(a.title)}</p>
              <div class="desc">${esc(a.body)}</div>
            </div>`;
  }).join('\n');
}

function buildSkillGroup(label, skills) {
  const vals = skills.map((s, i) => {
    const primary = i < 2 ? ' primary' : '';
    const comma = i < skills.length - 1 ? '<span class="comma">,</span>' : '';
    return `<span class="val${primary}">${esc(s)}</span>${comma}`;
  }).join('\n                ');
  return `
            <div class="skill-group">
              <span class="key">"${label}"</span><span class="o">:</span> <span class="open">[</span>
              <div class="arr">
                ${vals}
              </div>
              <span class="close">]${label === 'frontend' ? ',' : ''}</span>
            </div>`;
}

