const resume = $input.first().json.resume;

function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function buildExperience(entries) {
  return entries.map(exp => {
    const where = exp.location ? `<span class="where">${esc(exp.location)}</span>` : '';
    const bullets = exp.bullets.map(b => `              <li>${esc(b)}</li>`).join('\n');
    return `
          <div class="entry">
            <div class="entry-head">
              <p class="role">${esc(exp.title)}</p>
              <span class="when">${esc(exp.date)}</span>
            </div>
            <p class="org-line"><span class="accent">${esc(exp.org)}</span>${where}</p>
            <ul class="bullets">
${bullets}
            </ul>
          </div>`;
  }).join('\n');
}

function buildEducation(entries) {
  return entries.map(edu => {
    return `
          <div class="entry entry-compact">
            <div class="entry-head">
              <p class="role">${esc(edu.degree)}</p>
              <span class="when">${esc(edu.date)}</span>
            </div>
            <p class="org-line"><span class="accent">${esc(edu.school)}</span></p>
            ${edu.location ? `<p class="meta-line">${esc(edu.location)}</p>` : ''}
          </div>`;
  }).join('\n');
}

function buildAchievements(achs) {
  return achs.map(a => {
    return `
          <div class="ach">
            <div class="body">
              <p class="title">${esc(a.title)}</p>
              <div class="desc">${esc(a.body)}</div>
            </div>
          </div>`;
  }).join('\n');
}

function buildSkills(label, skills) {
  const items = skills.map((s, i) => {
    if (i < 2) return `<span class="primary">${esc(s)}</span>`;
    return esc(s);
  }).join(', ');
  return `
            <div class="row">
              <dt>${esc(label)}</dt>
              <dd>${items}</dd>
            </div>`;
}

function buildLanguages(langs) {
  return langs.map(l => {
    const code = l.dots >= 5 ? 'C2' : l.dots >= 4 ? 'B2' : l.dots >= 3 ? 'B1' : 'A2';
    return `            <div class="row"><span class="lname">${esc(l.name)}</span><span class="level">${esc(l.level)} <span class="code">${code}</span></span></div>`;
  }).join('\n');
}

function highlightSummary(text) {
  const highlights = ['React Native', 'Next.js', 'AI-driven automation', 'AI', 'Node.js', 'TypeScript'];
  let result = esc(text);
  for (const term of highlights) {
    const escaped = esc(term);
    const regex = new RegExp(escaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    result = result.replace(regex, `<span class="hl">${escaped}</span>`);
  }
  return result;
}

function taglineWithCode(headline) {
  const techTerms = ['React Native', 'Next.js', 'Node.js', 'Node', 'TypeScript', 'React', 'Expo'];
  let result = esc(headline);
  for (const term of techTerms) {
    const escaped = esc(term);
    const regex = new RegExp(escaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    result = result.replace(regex, `<code>${escaped}</code>`);
  }
  return result;
}

