<body>

<main class="sheet" data-screen-label="Resume — Behance">

  <!-- ====== Header ====== -->
  <header class="header">
    <div class="head-row">
      <div class="left">
        <h1 class="name">${esc(firstName)} <span class="accent">${esc(lastName)}</span></h1>
