        <div><span class="k">Based</span><span class="v">${esc(resume.contact.location)}</span></div>
      </div>
    </div>
  </header>

  <!-- ====== Two-column body ====== -->
  <div class="main">
    <div class="grid">

      <section class="col-left">

        <section>
          <h2 class="section-label">
