const items = $input.all();

return items.filter(item => {
  const status = (item.json.job_status || '').toLowerCase();

  // Skip expired/closed jobs
  if (['expired', 'closed', 'offline', 'paused'].includes(status)) {
    return false;
  }

  // Skip jobs with no description (broken listings)
  if (!item.json.description_full && !item.json.description_snippet) {
    return false;
  }

  return true;
});

const allUrls = [];
const seen = new Set();
const jobIdRegex = /linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/g;

for (const item of $('Get many messages').all()) {
  const text = item.json.text || item.json.snippet || '';

  let match;
  while ((match = jobIdRegex.exec(text)) !== null) {
    const jobId = match[1];
    if (!seen.has(jobId)) {
      seen.add(jobId);
      allUrls.push(`https://www.linkedin.com/jobs/view/${jobId}`);
    }
  }
}

return [{ json: { directUrls: allUrls } }];

const items = $input.all();
const cvId = items[0]?.json?.cvId;
let company;
try {
  company = $('Iterate vacancy').first().json.companyName;
} catch (e) {
  company = items[0]?.json?.companyName || 'Resume';
}

const safeName = company.replace(/[^a-zA-Z0-9]/g, '_');
const fullName = $('Configuration').first().json.candidate_raw_cv.full_name.replace(/\\s+/g, '_');


for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = `${fullName}_${safeName}.pdf`;
  }
  item.json.cvId = cvId;
}

return items;

